import{F as e,W as t,_ as n,f as r,g as i,h as a,j as o,l as s,n as c}from"./chunks/shared.rYHlazZf.js";var l=JSON.parse(`{"title":"Configure regras de pontos","description":"","frontmatter":{"title":"Configure regras de pontos","docId":"user.points.rules","translationKey":"user.points.rules","locale":"pt","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"ab201868f1511c20d8d26bb222e53b871620b44d591f083abf2d1b61bb340e31","translationRevision":"7e34723eee24dd2dd44fb258f9ba78c1464b8d7a9a35e4aa7e739522067e3e6c","order":10},"headers":[],"relativePath":"pt/user/points/rules.md","filePath":"pt/user/points/rules.md","lastUpdated":1795727787000}`),u={name:`pt/user/points/rules.md`};function d(c,l,u,d,f,p){let m=e(`DemoFrame`),h=e(`DocSteps`),g=e(`DocCallout`);return o(),r(`div`,null,[l[2]||=a(`<h1 id="configure-point-rules" tabindex="-1">Configure regras de pontos <a class="header-anchor" href="#configure-point-rules" aria-label="Permalink to “Configure regras de pontos”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Objetivo e pré-requisitos”">​</a></h2><p>Escolha como a atividade recebida ganha sua moeda local e depois verifique uma atribuição simples. Você precisa do TikTools em execução e de um criador conhecido para uma verificação posterior em LIVE. Regras de pontos e ações de automação são separadas: uma regra pode atribuir pontos mesmo sem nenhuma automação criada.</p><h2 id="set-the-earning-policy" tabindex="-1">Defina a política de ganhos <a class="header-anchor" href="#set-the-earning-policy" aria-label="Permalink to “Defina a política de ganhos”">​</a></h2>`,4),n(m,{scenario:`points`,locale:`pt`,panel:`points`,title:`Explore as regras e os saldos de pontos`}),n(h,null,{default:t(()=>[...l[0]||=[s(`ol`,null,[s(`li`,null,[i(`Abra `),s(`strong`,null,`Pontos`),i(` e localize o painel de regras. Escolha um nome de moeda reconhecível, como `),s(`code`,null,`Estrelas`),i(`.`)]),s(`li`,null,`Ative apenas as fontes desejadas: moedas de presentes, chat, curtidas, compartilhamentos, novos seguidores ou entradas. Cada fonte tem sua própria taxa e interruptor de ativação.`),s(`li`,null,[i(`Para uma primeira verificação simples, ative chat com `),s(`code`,null,`1`),i(` ponto e desative as outras fontes. Deixe o bônus de assinante em `),s(`code`,null,`0`),i(` enquanto estabelece a referência.`)]),s(`li`,null,[i(`Defina os pontos por nível, por exemplo `),s(`code`,null,`100`),i(`. O editor impõe um mínimo de `),s(`code`,null,`10`),i(`; as taxas não podem ser negativas.`)]),s(`li`,null,[i(`Selecione `),s(`strong`,null,`Salvar regras`),i(` e aguarde a confirmação. `),s(`strong`,null,`Descartar`),i(` restaura a configuração salva enquanto você ainda está editando.`)]),s(`li`,null,[i(`Conecte-se por `),s(`a`,{href:`./../live/connections.html`},`Conexões`),i(`, observe um novo evento de chat no `),s(`a`,{href:`./../live/feed.html`},`feed`),i(`, atualize a classificação e pesquise esse espectador.`)])],-1)]]),_:1}),l[3]||=a(`<p>As taxas de presentes e curtidas usam as quantidades de contribuição recebidas. Por exemplo, uma contribuição de <code>10</code> curtidas a <code>0.1</code> ponto por curtida produz <code>1</code> ponto antes de qualquer bônus aplicável. Uma linha exibida no feed não é necessariamente uma unidade de contribuição. Alterar as taxas define a política para atribuições seguintes; não espere um recálculo do passado.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado e status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “Resultado esperado e status”">​</a></h2><p>Regras locais, saldos de espectadores e controles manuais de adicionar/deduzir estão disponíveis. Com a configuração isolada de chat, uma nova mensagem aceita deve aumentar em um o saldo do espectador. Os níveis seguem o valor configurado de pontos por nível. Esses são pontos locais do aplicativo, não moeda do TikTok nem promessa de pagamento.</p><h2 id="recovery" tabindex="-1">Recuperação <a class="header-anchor" href="#recovery" aria-label="Permalink to “Recuperação”">​</a></h2><p>Verifique primeiro o interruptor da fonte, a taxa salva e o identificador do espectador. Uma automação que também atribui pontos pode adicionar uma segunda atribuição. Os controles de redefinição ficam bloqueados durante conexões LIVE ativas/em andamento; desconecte antes de uma redefinição planejada e leia sua confirmação. Mantenha um <a href="./../preferences/backups.html">backup com o aplicativo fechado</a> antes de limpar saldos acumulados.</p>`,5),n(g,{title:`Compare um evento com um saldo`,tone:`tip`},{default:t(()=>[...l[1]||=[s(`p`,null,`Salve apenas a regra de chat a 1 ponto e confira o mesmo espectador antes e depois de uma nova mensagem. Verifique também se alguma automação adiciona pontos para esse evento.`,-1)]]),_:1}),l[4]||=a(`<h2 id="operational-details" tabindex="-1">Detalhes de operação <a class="header-anchor" href="#operational-details" aria-label="Permalink to “Detalhes de operação”">​</a></h2><p>O menu da linha zera os pontos de um espectador, define nível 1 e acrescenta um marcador. <strong>Zerar todos</strong> afeta todos os espectadores salvos nesta instalação, entre criadores: zera saldos, define nível 1 e apaga o histórico de transações de pontos. Mantém os registros e contadores acumulados. Não limpa o feed nem o Analytics. Desconecte a LIVE, faça uma cópia com o aplicativo fechado e confira o alcance antes de confirmar.</p><p>Ajustes manuais positivos recebem o bônus de assinante salvo: +100 com bônus de 50% concede +150 a um assinante. Descontar 100 não recebe esse bônus; o saldo mínimo é zero. Confira o saldo final em vez de presumir um delta exato. A tabela busca apenas na sua captura dos 100 primeiros; um nome ausente não comprova ausência de registro.</p><h2 id="command-line-operations" tabindex="-1">Operações de linha de comando <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “Operações de linha de comando”">​</a></h2><p>Cada operação deste guia também está disponível na CLI — offline, scriptável e apta para agentes. As linhas de uso são sintaxe do parser e permanecem em inglês em todos os idiomas.</p><table tabindex="0"><thead><tr><th>Comando</th><th>Resumo</th></tr></thead><tbody><tr><td><code>tiktools points config get</code></td><td>ler a configuração de pontos</td></tr><tr><td><code>tiktools points config set k=v...</code></td><td>atualizar a configuração de pontos</td></tr><tr><td><code>tiktools points viewer get &lt;id&gt;</code></td><td>ler o saldo de um espectador</td></tr><tr><td><code>tiktools points adjust &lt;id&gt; &lt;delta&gt;</code></td><td>somar ou subtrair pontos de um espectador</td></tr><tr><td><code>tiktools points leaderboard [--limit N]</code></td><td>espectadores com maior saldo</td></tr><tr><td><code>tiktools points reset [id]</code></td><td>redefinir o saldo de um espectador ou de todos <strong>destrutivo</strong></td></tr></tbody></table><p>Consulte a <a href="./../../developer/cli.html">referência completa de comandos</a> para as convenções, a saída JSON e os marcadores de operações destrutivas.</p>`,7)])}var f=c(u,[[`render`,d]]);export{l as __pageData,f as default};